import Handlebars from 'handlebars';
import round from '../helper/funcs/round';

Handlebars.registerHelper('round', round);

describe('round helper', () => {
  it('should round a number to 0 decimal places by default', () => {
    const template = Handlebars.compile('{{round 3.14159265359}}');
    const result = template({});
    expect(result).toBe('3');
  });

  it('should round a number to specified decimal places (dec="2")', () => {
    const template = Handlebars.compile('{{round 3.14159265359 dec="2"}}');
    const result = template({});
    expect(result).toBe('3.14');
  });

  it('should round a number to 6 decimal places (dec="6")', () => {
    const template = Handlebars.compile('{{round 3.14159265359 dec="6"}}');
    const result = template({});
    expect(result).toBe('3.141593');
  });

  it('should round down the number (floor=true)', () => {
    const template = Handlebars.compile('{{round 3.14159265359 floor=true}}');
    const result = template({});
    expect(result).toBe('3');
  });

  it('should round down the number to specified decimal places (floor=true, dec="2")', () => {
    const template = Handlebars.compile('{{round 3.999 floor=true dec="2"}}');
    const result = template({});
    expect(result).toBe('3.00');
  });

  it('should return an empty string for invalid numbers', () => {
    const template = Handlebars.compile('{{round "invalid number"}}');
    const result = template({});
    expect(result).toBe('');
  });

  it('should handle rounding integers with no decimals', () => {
    const template = Handlebars.compile('{{round 5 dec="2"}}');
    const result = template({});
    expect(result).toBe('5.00');
  });

  it('should handle negative numbers', () => {
    const template = Handlebars.compile('{{round -3.14159 dec="3"}}');
    const result = template({});
    expect(result).toBe('-3.142');
  });

  it('should handle 0', () => {
    const template = Handlebars.compile('{{round 0 dec="2"}}');
    const result = template({});
    expect(result).toBe('0.00');
  });

  it('should handle rounding down 0 (floor=true)', () => {
    const template = Handlebars.compile('{{round 0 floor=true dec="2"}}');
    const result = template({});
    expect(result).toBe('0.00');
  });
});
